from content_core import *
def build():
 out=[]
 def a(topic,sub,stem,ans,chk,sol,wrong,art=''):
  n=len(out)+1;out.append(item(10,'november-mock',n,topic,sub,min(5,(n+4)//5),stem,ans,chk,sol,wrong,art,True))
 a(AR,'Unit prices','A print shop charges 8 credits to start a job and 3 credits per poster. Two groups pool orders of 7 and 9 posters into a single job. How many credits do they save?',8,(8+3*7)+(8+3*9)-(8+3*16),'The per-poster charges do not change. A pooled order uses one start charge instead of two, saving 8.',[3,6,16,24])
 a(ALG,'Linear equations','One rectangular flag is 3 units wider and 2 units shorter than a square flag of side s. Their areas are equal. What is s?',6,next(t for t in range(3,60) if (t+3)*(t-2)==t*t),'Expand (s+3)(s−2)=s² to obtain s²+s−6=s². Therefore s=6.',[3,4,5,8])
 a(SEQ,'Periodic sequences','A counter repeatedly cycles through 4, 1, 3, 2. What is the sum of its first 39 readings?',98,sum([4,1,3,2][i%4] for i in range(39)),'Nine full cycles contribute 90, and the next three terms contribute 4+1+3=8. Total 98.',[90,96,99,100])
 a(GEO,'Scale','A scale drawing shows a courtyard as a 3 cm by 5 cm rectangle. The actual perimeter is 64 m. What is its actual area in square metres?',240,(F(64,2*(3+5)))**2*15,'The perimeter scale is 64/16=4 metres per centimetre. The actual sides are 12 and 20 m, giving area 240.',[60,120,192,256])
 a(PRO,'Median','Five distinct positive integers have median 8 and maximum 14. What is the greatest possible sum of all five?',48,max(sum(v) for v in combinations(range(1,15),5) if v[2]==8 and v[-1]==14),'The two lower values can be at most 6 and 7; the value between 8 and 14 can be at most 13. Thus 6+7+8+13+14=48, which is attainable.',[43,46,47,50])
 a(NT,'Remainders','A four-digit number is made by writing the same two-digit number twice. What is the largest prime that divides every such four-digit number?',101,math.gcd(*(101*n for n in range(10,100))),'Repeating n produces 100n+n=101n. Consecutive n have no common prime factor, and 101 is prime. Hence 101 is the largest universal prime divisor.',[11,37,97,103])
 a(CNT,'Grouping','Six different paintings go into two identical portfolios with three paintings in each. How many divisions are possible?',10,len({min(tuple(c),tuple(sorted(set(range(6))-set(c)))) for c in combinations(range(6),3)}),'There are C(6,3)=20 ways to choose a named first portfolio. The portfolios are identical, so every division is counted twice: 10.',[6,15,20,40])
 a(AR,'Relative motion','A moving walkway carries a standing passenger its full length in 90 seconds. A passenger walking at constant speed on the stationary walkway takes 60 seconds. How long does the walking passenger take when the walkway assists?',36,1/(F(1,90)+F(1,60)),'The combined rate is 1/90+1/60=1/36 walkway per second. One walkway takes 36 seconds.',[24,30,45,75])
 a(ALG,'Factoring','Positive integers a and b satisfy ab+2a+2b=31. What is the largest possible value of a+b?',8,max(a+b for a in range(1,34) for b in range(1,34) if a*b+2*a+2*b==31),'Add 4: (a+2)(b+2)=35. Both factors exceed 2, so they must be 5 and 7. Thus the unordered values are 3 and 5, of sum 8.',[6,7,10,12])
 a(GEO,'Tangency','A circle is inscribed in a right triangle with legs 8 and 15. What is its radius?',3,F(8*15,8+15+17),'The hypotenuse is 17. The area equals inradius times semiperimeter, so r=60/20=3.',[2,4,5,F(15,4)])
 a(PRO,'Expected value','Three fair coins are tossed. For each pair of coins showing the same face, one token is earned. What is the expected number of tokens?',F(3,2),F(sum(sum(s[i]==s[j] for i,j in combinations(range(3),2)) for s in product("HT",repeat=3)),8),'There are three pairs. Each pair matches with probability 1/2, so linearity of expectation gives 3/2 tokens.',[F(3,4),1,2,F(9,4)])
 a(SEQ,'Arithmetic progressions','Six numbers in arithmetic progression have sum 51. The third and fifth differ by 6, with the fifth larger. What is the first number?',1,next(n for n in range(-20,40) if sum(n+3*i for i in range(6))==51),'The common difference is 3. The mean of the six terms is 8.5 and equals the first term plus 2.5 differences. Thus the first term is 8.5−7.5=1.',[2,3,4,5])
 a(NT,'Trailing zeros','A number N is the product 11 · 12 · … · 30. How many zeros are at the end of its decimal representation?',5,len(str(math.prod(range(11,31))))-len(str(math.prod(range(11,31))).rstrip('0')),'The number of 5 factors is one each from 15 and 20, two from 25, one from 30: five. There are more than five factors of 2, giving five trailing zeros.',[3,4,6,7])
 a(CNT,'Paths','A robot on a line makes five moves, each either +2 or −1. How many move strings end at 1, starting at 0, without ever going below 0?',3,sum(sum(p)==1 and min(itertools.accumulate(p))>=0 for p in product([2,-1],repeat=5)),'To finish at 1 requires two +2 moves and three −1 moves. The first move must be +2. The second +2 can be in slot 2, 3 or 4; slot 5 would mean three drops first. Thus there are three strings.',[2,4,5,10])
 a(ALG,'Absolute value','The graph y=|x−2|+|x+3| contains a horizontal segment. What is the product of its length and its height above the x-axis?',25,(2-(-3))*(abs(0-2)+abs(0+3)),'For −3≤x≤2 the distances to the endpoints sum to 5. Outside that interval the sum changes. The segment has length 5 and height 5, giving 25.',[5,10,15,20])
 a(GEO,'Area ratios','A trapezoid has parallel bases 4 and 10. The line joining the midpoints of its nonparallel sides cuts it into two pieces. What fraction of the total area belongs to the piece touching the shorter base?',F(11,28),F((4+7),2*(4+10)),'The midpoint line has length 7; each piece has half the original height. The two areas are proportional to 4+7 and 7+10, so the required part is 11/28.',[F(2,7),F(4,11),F(1,2),F(17,28)])
 a(LOG,'Extremal sets','A school chooses representatives from eight clubs of six students each. Each student belongs to exactly one club. What is the fewest representatives that guarantee at least four come from the same club?',25,1+sum(3 for _ in range(8)),'Without four from one club, at most three can come from each of eight clubs, for 24. That arrangement is possible. One more representative forces a fourth.',[22,23,24,28])
 a(NT,'Square divisors','How many positive integers divide 2⁶ · 3⁴ · 5² and have a perfect-square quotient when they divide that number?',24,sum(1 for i,j,k in product(range(7),range(5),range(3)) if math.isqrt((2**6*3**4*5**2)//(2**i*3**j*5**k))**2==(2**6*3**4*5**2)//(2**i*3**j*5**k)),'The quotient is square exactly when each remaining exponent is even. Exponents chosen in the divisor must therefore be even: 4 choices for 2, 3 for 3, and 2 for 5. Multiply to get 24.',[12,18,36,105])
 a(GEO,'Coordinate distances','The points (0,0) and (6,2) are opposite vertices of a square. What is the sum of the absolute values of the coordinates of both other vertices?',12,sum(abs(t) for p in [(3-1,1+3),(3+1,1-3)] for t in p),'The midpoint is (3,1). Rotate the half-diagonal (3,1) through 90° to (−1,3). The other vertices are (2,4) and (4,−2). The four absolute values sum to 12.',[6,10,14,16])
 a(PRO,'Conditioning','Two fair six-sided dice are rolled. Given that at least one die shows an even number, what is the probability that their sum is divisible by 3?',F(1,3),F(sum((a+b)%3==0 and (a%2==0 or b%2==0) for a,b in product(range(1,7),repeat=2)),27),'Nine odd–odd pairs are excluded, leaving 27. Twelve of the original pairs have sum divisible by 3, of which three are odd–odd: (1,5),(3,3),(5,1). Thus 9/27=1/3.',[F(1,4),F(2,9),F(4,9),F(1,2)])
 a(ALG,'Quadratic optimisation','Positive integers x,y satisfy 2x+y=29. What is the largest possible product xy?',105,max(x*(29-2*x) for x in range(1,15)),'The product is x(29−2x), a downward parabola with vertex at x=29/4. Compare neighbouring integers 7 and 8, giving 105 and 104. The maximum is 105.',[98,100,104,108])
 a(CNT,'Circular arrangements','Seven different musicians stand in a circle, with rotations identified and reflections distinct. Three specified musicians must stand consecutively as a single group. How many arrangements are possible?',144,math.factorial(4)*math.factorial(3),'Treat the trio as one block plus four single musicians: five objects on a circle give 4! arrangements. The trio can be ordered in 3! ways, for 24×6=144.',[72,120,240,720])
 a(SEQ,'Recurrences','An integer sequence starts a₁=2 and a₂=5, with aₙ₊₂=2aₙ₊₁−aₙ+2. Find a₁₁.',122,2+sum(3+2*i for i in range(10)),'Successive differences start at 3 and increase by 2: 3,5,…,21. The ten differences sum to 120, so a₁₁=122.',[100,112,120,132])
 a(NT,'Rational equations','How many ordered pairs of positive integers (x,y) satisfy 1/x+1/y=1/12?',15,sum((12*x)%(x-12)==0 for x in range(13,157)),'Rearrange to (x−12)(y−12)=144. Both factors are positive. Each positive divisor of 144=2⁴·3² determines exactly one ordered pair; there are 5×3=15 divisors.',[8,12,16,18])
 a(GEO,'Counting intersections','Eight points lie on a circle. Draw every chord joining two points. No three chords meet at a common interior point. Into how many regions do these chords divide the disk?',99,1+math.comb(8,2)+math.comb(8,4),'Each added chord creates one more region than the number of intersections it meets in its interior. There are C(8,2)=28 chords and C(8,4)=70 crossings, one per choice of four endpoints. Include the initial region: 1+28+70=99.',[70,93,98,100])
 return out
